def check_power_of_five(num):
    if num <= 0:
        return False, -1
    k = 0
    while num > 1:
        if num % 5 != 0:
            return False, -1
        num //= 5
        k += 1
    return True, k

results = {}
for n in range(3, 26):
    X = 2**n - 3
    is_power, k = check_power_of_five(X)
    if is_power:
        results[n] = k

print("Found solutions (n, k):")
for n, k in results.items():
    print(f"n={n}, k={k}")

print("\nFull results dictionary:")
print(results)

